import AppKit

final class ClipboardMonitor: NSObject {
    var onCapture: ((Capture) -> Void)?
    var isPaused = false
    var ignoresNextCopy = false {
        didSet { onIgnoreChanged?() }
    }
    var onIgnoreChanged: (() -> Void)?
    var maxItemBytes = 50 * 1024 * 1024
    var ignoredApps: Set<String> = []

    private static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    private let pasteboard = NSPasteboard.general
    private var lastChangeCount = -1
    private var timer: Timer?

    func start(interval: TimeInterval) {
        timer?.invalidate()
        let timer = Timer(timeInterval: interval, target: self, selector: #selector(poll), userInfo: nil, repeats: true)
        timer.tolerance = interval * 0.25
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    func skipCurrentChange() {
        lastChangeCount = pasteboard.changeCount
    }

    @objc private func poll() {
        let changeCount = pasteboard.changeCount
        guard changeCount != lastChangeCount else { return }
        lastChangeCount = changeCount
        guard !isPaused else { return }
        if ignoresNextCopy {
            ignoresNextCopy = false
            return
        }

        let sourceApp = NSWorkspace.shared.frontmostApplication?.bundleIdentifier
        if let sourceApp, ignoredApps.contains(sourceApp) { return }
        guard let reps = readPasteboard() else { return }
        onCapture?(Capture(representations: reps, sourceApp: sourceApp))
    }

    private func readPasteboard() -> [Representation]? {
        guard let items = pasteboard.pasteboardItems, !items.isEmpty else { return nil }
        if items.contains(where: { $0.types.contains { Self.skipTypes.contains($0.rawValue) } }) { return nil }

        var reps: [Representation] = []
        var total = 0
        for (index, item) in items.enumerated() {
            for type in item.types {
                guard let data = item.data(forType: type) else { continue }
                total += data.count
                if total > maxItemBytes {
                    NSLog("Clipsie: skipping clipboard content larger than \(maxItemBytes) bytes")
                    return nil
                }
                reps.append(Representation(itemIndex: index, type: type.rawValue, data: data))
            }
        }
        return reps.isEmpty ? nil : reps
    }
}
